// Netlify Function: setup-rich-menu
// สคริปต์ตั้งค่าครั้งเดียว (one-time admin action) — สร้าง Rich Menu บน LINE OA
// แบ่ง 2 ปุ่ม: "ลงทะเบียนอาคาร" (ซ้าย) และ "เช็ควันหมดอายุ" (ขวา)
// แล้วตั้งเป็นเมนูเริ่มต้นให้ผู้ติดตามทุกคนเห็น
//
// วิธีใช้: เปิด URL ของฟังก์ชันนี้ในเบราว์เซอร์ครั้งเดียว (GET หรือ POST ก็ได้)
// เช่น https://empowerbestsolution.com/.netlify/functions/setup-rich-menu
// รันซ้ำได้ปลอดภัย — จะสร้าง Rich Menu อันใหม่และตั้งเป็นค่าเริ่มต้นทับอันเก่าทุกครั้ง

const LINE_CHANNEL_ACCESS_TOKEN = process.env.LINE_CHANNEL_ACCESS_TOKEN;

// รูป Rich Menu (2500x843) เข้ารหัส base64 ไว้ในไฟล์นี้เลย ไม่ต้องพึ่งไฟล์ภายนอก
const RICH_MENU_IMAGE_BASE64 = "";

const RICH_MENU_DEFINITION = {
  size: { width: 2500, height: 843 },
  selected: true,
  name: "empower-main-menu",
  chatBarText: "เมนู",
  areas: [
    {
      bounds: { x: 0, y: 0, width: 1250, height: 843 },
      action: {
        type: "uri",
        label: "ลงทะเบียนอาคาร",
        uri: "https://liff.line.me/2011500534-lO4GZZ0d",
      },
    },
    {
      bounds: { x: 1250, y: 0, width: 1250, height: 843 },
      action: {
        type: "uri",
        label: "เช็ควันหมดอายุ",
        uri: "https://liff.line.me/2011500534-pv91WEcb",
      },
    },
  ],
};

function jsonResponse(statusCode, data) {
  return {
    statusCode,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data, null, 2),
  };
}

exports.handler = async () => {
  if (!LINE_CHANNEL_ACCESS_TOKEN) {
    return jsonResponse(500, { error: "ไม่พบ LINE_CHANNEL_ACCESS_TOKEN" });
  }

  try {
    // 1) สร้าง Rich Menu (ได้ richMenuId กลับมา)
    const createRes = await fetch("https://api.line.me/v2/bot/richmenu", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${LINE_CHANNEL_ACCESS_TOKEN}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(RICH_MENU_DEFINITION),
    });
    const createBody = await createRes.json();
    if (!createRes.ok) {
      return jsonResponse(500, {
        step: "create richmenu",
        status: createRes.status,
        error: createBody,
      });
    }
    const richMenuId = createBody.richMenuId;

    // 2) อัปโหลดรูปภาพให้กับ Rich Menu ที่สร้างไว้
    const imageBuffer = Buffer.from(RICH_MENU_IMAGE_BASE64, "base64");
    const uploadRes = await fetch(
      `https://api-data.line.me/v2/bot/richmenu/${richMenuId}/content`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${LINE_CHANNEL_ACCESS_TOKEN}`,
          "Content-Type": "image/png",
        },
        body: imageBuffer,
      }
    );
    if (!uploadRes.ok) {
      const uploadText = await uploadRes.text();
      return jsonResponse(500, {
        step: "upload image",
        status: uploadRes.status,
        error: uploadText,
        richMenuId,
      });
    }

    // 3) ตั้งเป็น Rich Menu เริ่มต้นให้ทุกคน
    const setDefaultRes = await fetch(
      `https://api.line.me/v2/bot/user/all/richmenu/${richMenuId}`,
      {
        method: "POST",
        headers: { Authorization: `Bearer ${LINE_CHANNEL_ACCESS_TOKEN}` },
      }
    );
    if (!setDefaultRes.ok) {
      const setDefaultText = await setDefaultRes.text();
      return jsonResponse(500, {
        step: "set default",
        status: setDefaultRes.status,
        error: setDefaultText,
        richMenuId,
      });
    }

    return jsonResponse(200, {
      success: true,
      richMenuId,
      message: "ตั้งค่า Rich Menu สำเร็จ และตั้งเป็นเมนูเริ่มต้นให้ทุกคนแล้ว",
    });
  } catch (err) {
    return jsonResponse(500, { error: String(err) });
  }
};
